/**
 * Base query text for a web-search-sourced platform, built from the campaign's
 * existing sourcing strategy (no new query-building system — reuses the boolean/
 * tag strings already generated by buildSourcingStrategy). The route scopes this
 * with `site:` per platform.
 */
function baseWebQuery(campaign: Campaign, platform: WebSearchPlatform): string {
  const jd = campaign.jobAnalysis;
  if (platform === "LinkedIn") return campaign.sourcingStrategy.linkedinBoolean;
  if (platform === "Stack Overflow") {
    const tags = campaign.sourcingStrategy.stackOverflowTags;
    return tags.length ? tags.map((t) => `"${t}"`).join(" OR ") : jd.title;
  }
  // Dribbble / Behance are portfolio platforms — a boolean recruiter string
  // doesn't fit; title + top skill is what a human would actually search.
  return [jd.title, jd.requiredSkills[0] ?? ""].filter(Boolean).join(" ");
}

/**
 * Parse the "Source via Sillage" dialog's single free-text field into the
 * identifier shape /api/source/sillage/start expects — a linkedin.com URL is
 * sent as linkedinUrl, anything else as a bare domain (protocol/www/path
 * stripped if the operator pasted a full URL).
 */
function parseSillageIdentifier(input: string): { domain?: string; linkedinUrl?: string } {
  const trimmed = input.trim();
  if (/linkedin\.com\//i.test(trimmed)) {
    return { linkedinUrl: /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}` };
  }
  return { domain: trimmed.replace(/^https?:\/\//i, "").replace(/^www\./i, "").split("/")[0] };
}

/**
 * Map real Sillage account-mapping profiles into scored, deduped Candidates —
 * the live counterpart to mapGithubCandidates/mapWebSearchCandidates (mock-ai.ts),
 * same scoring + dedupe pipeline, real data. Kept here rather than mock-ai.ts
 * because it needs the campaign's live effective weights, which only exist in
 * this client-side store — /api/source/sillage/status has no access to campaign
 * state and returns raw profiles only.
 */
function mapSillageCandidates(
  profiles: SillageProfile[],
  campaign: Campaign,
  companyLabel: string,
  existing: Candidate[],
  weights: ScoringWeights = campaign.scoringWeights,
): SourceResult {
  const jd = campaign.jobAnalysis;
  const allSkills = [...jd.requiredSkills, ...jd.niceToHaveSkills];
  const raw: Candidate[] = profiles.map((p) => {
    const name = [p.firstName, p.lastName].filter(Boolean).join(" ").trim() || "Unknown";
    const headline = (p.headline ?? "").trim();
    const about = (p.about ?? "").trim();
    const hay = `${p.position ?? ""} ${headline} ${about}`.toLowerCase();
    const techStack = allSkills.filter((s) => hay.includes(s.toLowerCase()));
    const location = [p.location?.city, p.location?.region, p.location?.country].filter(Boolean).join(", ");
    return {
      id: genId("cand"),
      campaignId: campaign.id,
      name,
      email: p.email ?? "",
      phone: p.phone ?? undefined,
      avatarInitials: initialsFrom(name),
      currentTitle: p.position || jd.title,
      currentCompany: companyLabel,
      location,
      timezone: "",
      linkedinUrl: p.linkedinUrl ?? "",
      githubUrl: "",
      sourcePlatform: "Sillage",
      sourceQuery: companyLabel,
      matchScore: 0,
      matchBreakdown: [],
      techStack,
      yearsExperience: jd.minYearsExperience ?? (jd.seniority === "Senior" ? 6 : 4),
      companyStageExperience: [],
      industryExperience: [],
      recentActivity: headline || about.slice(0, 140) || `Sourced via Sillage account mapping: ${companyLabel}.`,
      stage: "Sourced",
      lastContactedAt: null,
      outreachHistory: [],
      replyHistory: [],
      booking: null,
      complianceFlags: {
        doNotContact: false,
        suppressed: false,
        unsubscribed: false,
        gdprExportRequested: false,
        anonymized: false,
        suppressedUntil: null,
      },
      createdAt: new Date().toISOString(),
      provenance: "live",
    };
  });

  const { accepted, skipped } = dedupeCandidates(raw, existing, {
    excludedCompanies: campaign.sourcingStrategy.excludedCompanies,
  });
  const scored = accepted.map((c) => {
    const { score, breakdown } = scoreCandidate(c, jd, weights);
    return { ...c, matchScore: score, matchBreakdown: breakdown };
  });

import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import { getServerSupabase, requireAdmin } from "@/lib/supabase/server";
import { encryptSecret, encryptionRequiredButMissing } from "@/lib/crypto-secrets";
import { supabaseEnabled, prodFailClosed } from "@/lib/supabase/config";
import { last4Of, validateApiKeyFormat } from "@/lib/providers";
import { validateBody } from "@/lib/api/validate";
import { checkRateLimit, rateLimitKey, tooManyRequests } from "@/lib/rate-limit";
import { safeLog } from "@/lib/log-redact";

const ApiKeyCreateSchema = z.object({
  name: z.string().min(1).max(120),
  provider: z.string().min(1).max(80),
  value: z.string().min(1).max(1000),
});

/**
 * API key storage. Secrets are written to the `api_keys` table (admin-only via
 * RLS) and NEVER returned to the browser. In DEMO mode nothing persists
 * server-side — the response carries only metadata (last4) for the session.
 */
export async function POST(req: NextRequest) {
  // Fail closed in production (middleware doesn't cover /api/*).
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;

  // Auth-first: resolve and authorise the caller BEFORE parsing the body or
  // touching the secret. Demo mode (no Supabase) is intentionally open and only
  // echoes metadata.
  let supabase: Awaited<ReturnType<typeof getServerSupabase>> = null;
  let createdBy = "unknown";
  if (supabaseEnabled) {
    supabase = await getServerSupabase();
    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
    const admin = await requireAdmin(supabase);
    if (!admin.ok) return admin.response;
    const {
      data: { user },
    } = await supabase.auth.getUser();
    createdBy = user?.email ?? "unknown";
  }

  // Throttle: persisting secrets is sensitive — blunt abuse / accidental loops.
  const limit = checkRateLimit(rateLimitKey(req, "keys-create"), { windowMs: 60_000, max: 20 });
  if (!limit.ok) return tooManyRequests(limit.retryAfterSec);

  const validated = await validateBody(req, ApiKeyCreateSchema, { maxBytes: 8_000 });
  if (!validated.ok) return validated.response;
  const { name, provider, value } = validated.data;

  const last4 = last4Of(value);
  const fmt = validateApiKeyFormat(provider, value);

  if (!supabaseEnabled) {
    return NextResponse.json({
      ok: true,
      demo: true,
      last4,
      formatValid: fmt.valid,
      detail: "Saved for this session (demo). Configure Supabase to persist server-side.",
    });
  }

  if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });

  // Fail closed: never persist a new secret in cleartext when production requires
  // encryption at rest but DATA_ENCRYPTION_KEY isn't configured.
  if (encryptionRequiredButMissing()) {
    return NextResponse.json(
      { ok: false, error: "Server encryption key is not configured." },
      { status: 503 },
    );
  }

  const { data: wid } = await supabase.rpc("ensure_workspace");
  // select("id") only: `authenticated` has no column-level SELECT grant on
  // `secret` (by design — it must never round-trip to the browser), and an
  // unqualified .select() asks PostgREST to RETURNING * (every column),
  // which Postgres then denies wholesale as "permission denied for table".
  const { data, error } = await supabase
    .from("api_keys")
    .insert({ workspace_id: wid, name, provider, secret: encryptSecret(value), last4, created_by: createdBy })
    .select("id");
  if (error) {
    // Log the DB detail server-side (redacted); never echo Postgres/RLS internals to the client.
    safeLog("api_keys insert error", { message: error.message, code: error.code });
    return NextResponse.json({ ok: false, error: "Couldn't save the key. Try again." }, { status: 403 });
  }
  return NextResponse.json({ ok: true, id: data[0].id, last4, formatValid: fmt.valid });
}

export async function DELETE(req: NextRequest) {
  // Fail closed in production (middleware doesn't cover /api/*).
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;

  // Auth-first: authorise BEFORE validating input or returning anything.
  let supabase: Awaited<ReturnType<typeof getServerSupabase>> = null;
  if (supabaseEnabled) {
    supabase = await getServerSupabase();
    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
    const admin = await requireAdmin(supabase);
    if (!admin.ok) return admin.response;
  }

  const limit = checkRateLimit(rateLimitKey(req, "keys-delete"), { windowMs: 60_000, max: 20 });
  if (!limit.ok) return tooManyRequests(limit.retryAfterSec);

  const id = new URL(req.url).searchParams.get("id");
  if (!id || !z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ ok: false, error: "Missing or invalid id." }, { status: 400 });
  }

  if (!supabaseEnabled) return NextResponse.json({ ok: true, demo: true });
  if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
  const { error } = await supabase.from("api_keys").delete().eq("id", id);
  if (error) {
    safeLog("api_keys delete error", { message: error.message, code: error.code });
    return NextResponse.json({ ok: false, error: "Couldn't delete the key. Try again." }, { status: 403 });
  }
  return NextResponse.json({ ok: true });
}

import type { Role } from "./types";

/* ============================================================================
   Role-based access control.
   admin  — full control (settings, API keys, roles, fleet, all operations)
   member — operates the pipeline (source, outreach, book, replies, skills,
            compliance actions) but cannot manage settings/keys/roles/fleet
   viewer — read-only
   ========================================================================== */

export const PERMISSIONS = [
  "view",
  "source",
  "outreach",
  "book",
  "reply",
  "skills",
  "compliance",
  "manage_fleet",
  "manage_settings",
  "manage_keys",
  "manage_roles",
  "manage_providers",
  "manage_models",
  "manage_tools",
] as const;
export type Permission = (typeof PERMISSIONS)[number];

const ROLE_PERMS: Record<Role, Permission[]> = {
  admin: [...PERMISSIONS],
  member: ["view", "source", "outreach", "book", "reply", "skills", "compliance"],
  viewer: ["view"],
};

// Admin gets all permissions including the new LLM-config trio.
// Member and viewer remain unchanged — only admins configure providers/models/tools.

export function can(role: Role, perm: Permission): boolean {
  return ROLE_PERMS[role]?.includes(perm) ?? false;
}

export const ROLE_LABEL: Record<Role, string> = {
  admin: "Admin",
  member: "Member",
  viewer: "Viewer",
};

export const ROLE_DESCRIPTION: Record<Role, string> = {
  admin: "Full control: settings, API keys, roles, fleet, and every operation.",
  member: "Operates the pipeline: source, outreach, booking, replies, skills. No settings/keys/roles/fleet.",
  viewer: "Read-only: can see everything, change nothing.",
};

