-- ============================================================================
-- Hermes Sourcing — initial schema
-- Shared-org workspace model. Each org (by email domain) has one workspace and
-- one JSONB state document. RLS scopes all access to the caller's workspace.
-- Run in the Supabase SQL editor (or `supabase db push`).
-- ============================================================================

create extension if not exists "pgcrypto";

-- ---- Tables ----------------------------------------------------------------

create table if not exists public.workspaces (
  id             uuid primary key default gen_random_uuid(),
  name           text not null,
  allowed_domain text unique,
  created_at     timestamptz not null default now()
);

create table if not exists public.profiles (
  id           uuid primary key references auth.users(id) on delete cascade,
  email        text,
  full_name    text,
  workspace_id uuid references public.workspaces(id) on delete set null,
  role         text not null default 'member',
  created_at   timestamptz not null default now()
);

create table if not exists public.workspace_state (
  workspace_id uuid primary key references public.workspaces(id) on delete cascade,
  state        jsonb not null default '{}'::jsonb,
  updated_at   timestamptz not null default now()
);

-- ---- Row Level Security ----------------------------------------------------

alter table public.workspaces       enable row level security;
alter table public.profiles         enable row level security;
alter table public.workspace_state  enable row level security;

-- SECURITY DEFINER helper avoids recursive RLS when policies reference profiles.
create or replace function public.current_workspace_id()
returns uuid
language sql stable security definer set search_path = public as $$
  select workspace_id from public.profiles where id = auth.uid();
$$;

-- a user's own role, read via SECURITY DEFINER so the update policy can pin it
create or replace function public.current_profile_role()
returns text language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid();
$$;

-- profiles: a user owns their own row, but CANNOT self-assign workspace_id or role
-- (those are set only by ensure_workspace(), which is SECURITY DEFINER and bypasses RLS).
drop policy if exists "own profile read"   on public.profiles;
drop policy if exists "own profile insert" on public.profiles;
drop policy if exists "own profile update" on public.profiles;
create policy "own profile read" on public.profiles for select using (id = auth.uid());
-- self-insert only with no chosen workspace and the default role
create policy "own profile insert" on public.profiles for insert
  with check (id = auth.uid() and workspace_id is null and role = 'member');
-- on update, workspace_id and role must stay exactly as stored (anti tenant-hop / escalation)
create policy "own profile update" on public.profiles for update
  using (id = auth.uid())
  with check (
    id = auth.uid()
    and workspace_id is not distinct from public.current_workspace_id()
    and role is not distinct from public.current_profile_role()
  );

-- workspaces: members may read their workspace
drop policy if exists "members read workspace" on public.workspaces;
create policy "members read workspace" on public.workspaces for select
  using (id = public.current_workspace_id());

-- workspace_state: members may read + write their workspace's document
drop policy if exists "members read state"   on public.workspace_state;
drop policy if exists "members insert state" on public.workspace_state;
drop policy if exists "members update state" on public.workspace_state;
create policy "members read state"   on public.workspace_state for select
  using (workspace_id = public.current_workspace_id());
create policy "members insert state" on public.workspace_state for insert
  with check (workspace_id = public.current_workspace_id());
create policy "members update state" on public.workspace_state for update
  using (workspace_id = public.current_workspace_id());

-- ---- Bootstrap: find-or-create org workspace by email domain ---------------

create or replace function public.ensure_workspace()
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  uid    uuid := auth.uid();
  uemail text;
  domain text;
  wid    uuid;
begin
  if uid is null then
    raise exception 'not authenticated';
  end if;

  select email into uemail from auth.users where id = uid;
  domain := lower(split_part(coalesce(uemail, 'user@workspace'), '@', 2));
  if domain = '' then domain := 'workspace'; end if;

  -- already provisioned?
  select workspace_id into wid from public.profiles where id = uid;
  if wid is not null then
    return wid;
  end if;

  -- shared org workspace, keyed by domain
  select id into wid from public.workspaces where allowed_domain = domain;
  if wid is null then
    insert into public.workspaces(name, allowed_domain)
      values (initcap(domain) || ' Workspace', domain)
      returning id into wid;
  end if;

  insert into public.profiles(id, email, full_name, workspace_id)
    values (uid, uemail, split_part(coalesce(uemail, 'user'), '@', 1), wid)
    on conflict (id) do update
      set workspace_id = excluded.workspace_id, email = excluded.email;

  return wid;
end;
$$;

grant execute on function public.ensure_workspace()      to authenticated;
grant execute on function public.current_workspace_id()  to authenticated;
grant execute on function public.current_profile_role()  to authenticated;

-- keep updated_at fresh on state writes
create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists workspace_state_touch on public.workspace_state;
create trigger workspace_state_touch
  before update on public.workspace_state
  for each row execute function public.touch_updated_at();

-- ============================================================================
-- Hermes Sourcing — fleet guardrails (server-side enforcement)
-- Authoritative tables + an atomic claim RPC so the anti-double-contact and
-- per-account rate limits are enforced in Postgres, not just the client.
-- Coordination within official limits — never evasion. Email only.
-- Run AFTER 0001_init.sql.
-- ============================================================================

create table if not exists public.agent_seats (
  id                 uuid primary key default gen_random_uuid(),
  workspace_id       uuid not null references public.workspaces(id) on delete cascade,
  name               text not null,
  operator_email     text not null,
  provider           text not null default 'Microsoft Graph',
  status             text not null default 'active',
  mode               text not null default 'mock',
  domain_verified    boolean not null default false,
  daily_limit        int not null default 40,
  warmup             boolean not null default true,
  warmup_start_cap   int not null default 10,
  warmup_step_per_day int not null default 4,
  warmup_started_at  timestamptz not null default now(),
  min_gap_minutes    int not null default 12,
  persona            text not null default '',
  signature          text not null default '',
  connected_account  text not null default '',
  created_at         timestamptz not null default now()
);

create table if not exists public.suppression_list (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces(id) on delete cascade,
  type         text not null check (type in ('email','domain','linkedin')),
  value        text not null,
  reason       text not null default '',
  source       text not null default 'Operator',
  created_at   timestamptz not null default now(),
  expires_at   timestamptz,
  unique (workspace_id, type, value)
);

create table if not exists public.outreach_ledger (
  id              uuid primary key default gen_random_uuid(),
  workspace_id    uuid not null references public.workspaces(id) on delete cascade,
  candidate_id    text not null,
  candidate_email text not null,
  seat_id         uuid references public.agent_seats(id) on delete set null,
  campaign_id     text,
  channel         text not null default 'Email',
  status          text not null default 'sent',
  reason          text,
  at              timestamptz not null default now()
);

-- One active contact per candidate per workspace — the hard de-dupe guarantee.
create unique index if not exists outreach_ledger_active_uniq
  on public.outreach_ledger (workspace_id, candidate_id)
  where status in ('claimed','sent');

create index if not exists outreach_ledger_seat_day on public.outreach_ledger (seat_id, at);

-- ---- RLS ----
alter table public.agent_seats      enable row level security;
alter table public.suppression_list enable row level security;
alter table public.outreach_ledger  enable row level security;

do $$
declare t text;
begin
  foreach t in array array['agent_seats','suppression_list','outreach_ledger'] loop
    execute format('drop policy if exists "%s rw" on public.%I', t, t);
    execute format(
      'create policy "%s rw" on public.%I for all using (workspace_id = public.current_workspace_id()) with check (workspace_id = public.current_workspace_id())',
      t, t);
  end loop;
end $$;

-- ---- Atomic claim: suppression + re-contact window + per-seat daily cap ----
-- Returns json { allowed: bool, reason: text, ledger_id: uuid }.
create or replace function public.claim_and_record(
  p_candidate_id    text,
  p_candidate_email text,
  p_campaign_id     text,
  p_seat_id         uuid,
  p_channel         text default 'Email',
  p_recontact_days  int  default 90
) returns json
language plpgsql security definer set search_path = public as $$
declare
  wid        uuid := public.current_workspace_id();
  domain     text := lower(split_part(coalesce(p_candidate_email,''), '@', 2));
  seat       public.agent_seats%rowtype;
  used_today int;
  cap        int;
  new_id     uuid;
begin
  if wid is null then return json_build_object('allowed', false, 'reason', 'no workspace'); end if;

  -- suppression (email / domain)
  if exists (
    select 1 from public.suppression_list s
     where s.workspace_id = wid
       and (s.expires_at is null or s.expires_at > now())
       and ((s.type='email' and lower(s.value)=lower(p_candidate_email))
         or (s.type='domain' and lower(s.value)=domain))
  ) then
    return json_build_object('allowed', false, 'reason', 'suppressed');
  end if;

  -- re-contact window across the whole fleet
  if exists (
    select 1 from public.outreach_ledger l
     where l.workspace_id = wid and l.candidate_id = p_candidate_id
       and l.status in ('claimed','sent') and l.at > now() - make_interval(days => p_recontact_days)
  ) then
    return json_build_object('allowed', false, 'reason', 'recently contacted');
  end if;

  -- per-seat daily cap (effective warm-up cap)
  select * into seat from public.agent_seats where id = p_seat_id and workspace_id = wid;
  if not found then return json_build_object('allowed', false, 'reason', 'seat not found'); end if;
  if seat.status <> 'active' then return json_build_object('allowed', false, 'reason', 'seat not active'); end if;

  cap := seat.daily_limit;
  if seat.warmup then
    cap := least(seat.daily_limit,
                 greatest(seat.warmup_start_cap,
                          seat.warmup_start_cap + seat.warmup_step_per_day *
                          floor(extract(epoch from (now() - seat.warmup_started_at)) / 86400)::int));
  end if;

  select count(*) into used_today from public.outreach_ledger
   where seat_id = p_seat_id and at::date = now()::date and status in ('claimed','sent');
  if used_today >= cap then
    return json_build_object('allowed', false, 'reason', 'seat daily cap reached');
  end if;

  -- atomic insert as 'claimed' — holds the de-dupe slot (the unique index, daily
  -- cap and re-contact checks all include 'claimed'). The caller reconciles to
  -- 'sent' after the provider responds, or 'skipped' on failure (so it retries).
  begin
    insert into public.outreach_ledger(workspace_id, candidate_id, candidate_email, seat_id, campaign_id, channel, status)
      values (wid, p_candidate_id, p_candidate_email, p_seat_id, p_campaign_id, p_channel, 'claimed')
      returning id into new_id;
  exception when unique_violation then
    return json_build_object('allowed', false, 'reason', 'already contacted');
  end;

  return json_build_object('allowed', true, 'reason', 'ok', 'ledger_id', new_id);
end;
$$;

grant execute on function public.claim_and_record(text,text,text,uuid,text,int) to authenticated;

"use client";

import type { HermesState, Role } from "@/lib/types";
import { getBrowserSupabase } from "./client";
import { stripSharedRole } from "@/lib/live-role-authority";

function profileRole(value: unknown): Role {
  return value === "admin" || value === "member" || value === "viewer" ? value : "viewer";
}

export interface RemoteLoad {
  workspaceId: string;
  state: HermesState | null;
  /** Signed-in profile authority. Shared workspace JSON is never authoritative. */
  role: Role;
  /** The row's `updated_at` when loaded — the optimistic-concurrency token. */
  updatedAt: string | null;
}

export interface SaveResult {
  ok: boolean;
  /** True when the write was rejected because a teammate saved since we loaded. */
  conflict?: boolean;
  /** The new `updated_at` after a successful save (becomes the next token). */
  updatedAt?: string;
  /** On a conflict, the latest shared state to reload. */
  latest?: RemoteLoad;
}

export interface CurrentUser {
  id: string;
  email: string;
  name: string;
  role: Role;
}

/** Resolve the signed-in user (browser). Returns null in demo mode / signed out. */
export async function getCurrentUser(): Promise<CurrentUser | null> {
  const supabase = getBrowserSupabase();
  if (!supabase) return null;
  const { data } = await supabase.auth.getUser();
  const u = data.user;
  if (!u) return null;
  const name =
    (u.user_metadata?.full_name as string) ||
    (u.user_metadata?.name as string) ||
    (u.email ? u.email.split("@")[0] : "Operator");
  const { data: role } = await supabase.rpc("current_profile_role");
  return { id: u.id, email: u.email ?? "", name, role: profileRole(role) };
}

/**
 * Load this user's shared workspace state. `ensure_workspace` (a SECURITY DEFINER
 * function in the migration) finds-or-creates the org workspace by email domain
 * and the caller's profile, returning the workspace id. Returns null only when
 * signed out; otherwise returns the workspace id, its persisted state (or null if
 * the workspace has never been seeded), and the row's `updated_at` token.
 */
export async function loadRemoteState(): Promise<RemoteLoad | null> {
  const supabase = getBrowserSupabase();
  if (!supabase) return null;
  const { data: userData } = await supabase.auth.getUser();
  if (!userData.user) return null;

  try {
    const { data: workspaceId, error: rpcError } = await supabase.rpc("ensure_workspace");
    if (rpcError || !workspaceId) {
      console.warn("ensure_workspace failed; running in-memory only:", rpcError?.message);
      return { workspaceId: "", state: null, updatedAt: null, role: "viewer" };
    }
    const { data: resolvedRole, error: roleError } = await supabase.rpc("current_profile_role");
    if (roleError) {
      console.warn("current_profile_role failed; using read-only authority:", roleError.message);
    }
    const role = roleError ? "viewer" : profileRole(resolvedRole);
    const { data: row, error: rowError } = await supabase
      .from("workspace_state")
      .select("state, updated_at")
      .eq("workspace_id", workspaceId)
      .maybeSingle();
    if (rowError) {
      // A FAILED read must not masquerade as an EMPTY workspace: the hydrate
      // path seeds-and-saves when it sees `state: null` with a workspaceId,
      // which would overwrite the whole shared blob during a transient backend
      // blip. Run in-memory only (no workspaceId → nothing ever persists).
      console.warn("workspace_state load failed; running in-memory only:", rowError.message);
      return { workspaceId: "", state: null, updatedAt: null, role };
    }
    return {
      workspaceId: workspaceId as string,
      state: (row?.state as HermesState) ?? null,
      updatedAt: (row?.updated_at as string) ?? null,
      role,
    };
  } catch (err) {
    console.warn("loadRemoteState error:", err);
    return { workspaceId: "", state: null, updatedAt: null, role: "viewer" };
  }
}

/**
 * Persist the full workspace state document with OPTIMISTIC CONCURRENCY.
 *
 * `expectedUpdatedAt` is the `updated_at` the caller last loaded. The write only
 * lands if the row STILL has that timestamp — so if a teammate saved in the
 * meantime, the conditional update matches zero rows and we report a conflict
 * (with the latest state) instead of silently clobbering their change. The shared
 * workspace is one JSONB document, so last-write-wins would otherwise lose a whole
 * concurrent edit with no warning to anyone.
 *
 * When `expectedUpdatedAt` is null (first save, the row does not exist yet) we
 * upsert to create it.
 */
export async function saveRemoteState(
  workspaceId: string,
  state: HermesState,
  expectedUpdatedAt: string | null,
): Promise<SaveResult> {
  const supabase = getBrowserSupabase();
  if (!supabase || !workspaceId) return { ok: false };
  const sharedState = stripSharedRole(state);
  try {
    if (expectedUpdatedAt === null) {
      // No known prior version — create (or adopt) the row. `updated_at` is owned by
      // the DB (column default on insert, the touch_updated_at trigger on update),
      // so we read it back as the authoritative concurrency token rather than
      // trusting a client clock the trigger would overwrite anyway.
      const { data, error } = await supabase
        .from("workspace_state")
        .upsert({ workspace_id: workspaceId, state: sharedState }, { onConflict: "workspace_id" })
        .select("updated_at")
        .maybeSingle();
      if (error) {
        console.warn("saveRemoteState (insert) failed:", error.message);
        return { ok: false };
      }
      return { ok: true, updatedAt: (data?.updated_at as string) ?? undefined };
    }

    // Conditional update — only overwrite the exact version we loaded. The
    // touch_updated_at trigger assigns the new updated_at; we read it back as the
    // authoritative next token (never via a JS Date, which would drop microseconds).
    const { data, error } = await supabase
      .from("workspace_state")
      .update({ state: sharedState })
      .eq("workspace_id", workspaceId)
      .eq("updated_at", expectedUpdatedAt)
      .select("updated_at")
      .maybeSingle();
    if (error) {
      console.warn("saveRemoteState (update) failed:", error.message);
      return { ok: false };
    }
    if (!data) {
      // Zero rows matched → a teammate wrote since we loaded. Return the latest
      // state so the caller can reload instead of clobbering it.
      const { data: latestRow } = await supabase
        .from("workspace_state")
        .select("state, updated_at")
        .eq("workspace_id", workspaceId)
        .maybeSingle();
      return {
        ok: false,
        conflict: true,
        latest: {
          workspaceId,
          state: (latestRow?.state as HermesState) ?? null,
          updatedAt: (latestRow?.updated_at as string) ?? null,
          role: "viewer",
        },
      };
    }
    return { ok: true, updatedAt: data.updated_at as string };
  } catch (err) {
    console.warn("saveRemoteState error:", err);
    return { ok: false };
  }
}

export async function signOut(): Promise<void> {
  const supabase = getBrowserSupabase();
  if (!supabase) return;
  await supabase.auth.signOut();
}

import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import { domainVerified } from "@/lib/domain-verification";
import { getServerSupabase } from "@/lib/supabase/server";
import { supabaseEnabled, prodFailClosed } from "@/lib/supabase/config";
import { validateBody } from "@/lib/api/validate";
import { can } from "@/lib/rbac";
import type { Role } from "@/lib/types";
import { checkRateLimit, rateLimitKey, tooManyRequests } from "@/lib/rate-limit";

// Bare hostname only — labels of 1-63 alphanumerics/hyphens (no leading/trailing
// hyphen), at least one dot. Rejects URLs (no scheme/path chars allowed) and
// email addresses (no "@") by construction rather than by denylist.
const HOSTNAME_RE = /^(?!-)[a-zA-Z0-9-]{1,63}(?<!-)(\.(?!-)[a-zA-Z0-9-]{1,63}(?<!-))+$/;

const VerifyDomainSchema = z.object({
  seatId: z.string().uuid(),
  domain: z
    .string()
    .min(3)
    .max(253)
    .regex(HOSTNAME_RE, "Enter a bare domain (e.g. mail.example.com), not a URL or email address."),
});

/**
 * Verify a sending domain's SPF/DKIM/DMARC DNS records BEFORE a seat is allowed
 * to go live. This is the only path that lets an operator flip a seat's
 * `domain_verified` flag ahead of send time — mirrors the same DNS check the
 * send route (`/api/outreach/send`) otherwise only runs lazily on first live
 * send. `domainVerified` itself does the real DNS lookups; this route just
 * gates who may trigger it and persists the result.
 */
export async function POST(req: NextRequest) {
  // Fail closed in production (middleware doesn't cover /api/*): never serve the
  // open demo path unauthenticated.
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;

  // Tight rate limit — this endpoint does real DNS lookups per call.
  const rl = checkRateLimit(rateLimitKey(req, "outreach-verify-domain"), { windowMs: 60_000, max: 5 });
  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);

  const validated = await validateBody(req, VerifyDomainSchema, { maxBytes: 2_000 });
  if (!validated.ok) return validated.response;
  const { seatId, domain } = validated.data;

  // DEMO mode: no enforcement backend to persist against, but the DNS check
  // itself is real — let the operator see a genuine result, just don't persist.
  if (!supabaseEnabled) {
    const verified = await domainVerified(domain);
    return NextResponse.json({ ok: true, verified });
  }

  const supabase = await getServerSupabase();
  if (!supabase) {
    const verified = await domainVerified(domain);
    return NextResponse.json({ ok: true, verified });
  }

  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
  }
  // Authorization: same `outreach` permission the approve/send routes require.
  const { data: role } = await supabase.rpc("current_profile_role");
  if (!can(role as Role, "outreach")) {
    return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
  }

  // Seat must belong to the caller's workspace (RLS) — same lookup shape as the
  // send route's seat check.
  const { data: seat, error: seatErr } = await supabase
    .from("agent_seats")
    .select("id")
    .eq("id", seatId)
    .maybeSingle();
